using DriveOS.Application.Abstractions.Messaging;using DriveOS.Application.Abstractions.Time;using DriveOS.Modules.CurriculumPedagogy.Application.Competencies;using DriveOS.Modules.CurriculumPedagogy.Application.Persistence;using DriveOS.Modules.CurriculumPedagogy.Domain.PedagogicalReviews;using DriveOS.Modules.CurriculumPedagogy.Domain.RemediationPlans;using DriveOS.Modules.CurriculumPedagogy.Domain.TrainingPaths;using DriveOS.SharedKernel.Identifiers;using DriveOS.SharedKernel.Results;
namespace DriveOS.Modules.CurriculumPedagogy.Application.RemediationPlans;
public sealed class CreateRemediationPlanCommandHandler(ITrainingPathRepository paths,IRemediationPlanRepository plans,IPedagogicalReviewRepository reviews,ICurriculumCompetencyEligibilityService competencies,ICurriculumPedagogyUnitOfWork uow,IClock clock):ICommandHandler<CreateRemediationPlanCommand,RemediationPlanId>{public async Task<Result<RemediationPlanId>>Handle(CreateRemediationPlanCommand c,CancellationToken ct){var path=await paths.GetByIdAsync(c.TrainingPathId,c.OrganizationId,ct);if(path is null)return Result.Failure<RemediationPlanId>(RemediationPlanApplicationErrors.TrainingPathNotFound);if(path.Status is TrainingPathStatus.Draft or TrainingPathStatus.ReadyForActivation or TrainingPathStatus.Completed or TrainingPathStatus.Cancelled)return Result.Failure<RemediationPlanId>(RemediationPlanApplicationErrors.TrainingPathNotEligible);if(await plans.HasOpenPlanAsync(c.OrganizationId,c.TrainingPathId,ct))return Result.Failure<RemediationPlanId>(RemediationPlanApplicationErrors.OpenPlanExists);if(c.SourceReviewId.HasValue){var review=await reviews.GetByIdAsync(c.OrganizationId,c.SourceReviewId.Value,ct);if(review is null||review.TrainingPathId!=path.Id||review.Status!=PedagogicalReviewStatus.Completed)return Result.Failure<RemediationPlanId>(RemediationPlanApplicationErrors.SourceReviewInvalid);}var created=RemediationPlan.Create(RemediationPlanId.New(),c.OrganizationId,path.StudentId,path.Id,c.ResponsibleUserId,c.SourceReviewId,c.Recommendation,c.RecommendedPracticalHours,c.RecommendedSessions,c.ReviewDate,clock.UtcNow);if(created.IsFailure)return Result.Failure<RemediationPlanId>(created.Error);foreach(var target in c.Targets){if(await competencies.GetAsync(c.OrganizationId,path.CurriculumVersionId,target.CompetencyId,ct) is null)return Result.Failure<RemediationPlanId>(RemediationPlanApplicationErrors.CompetencyNotFound);var added=created.Value.AddTarget(RemediationPlanTargetId.New(),target.CompetencyId,target.Objective);if(added.IsFailure)return Result.Failure<RemediationPlanId>(added.Error);}await plans.AddAsync(created.Value,ct);await uow.CommitAsync(ct);return Result.Success(created.Value.Id);}}
public abstract class RemediationMutationBase(IRemediationPlanRepository plans,ICurriculumPedagogyUnitOfWork uow){protected async Task<Result<RemediationPlan>>Load(OrganizationId org,RemediationPlanId id,CancellationToken ct){var p=await plans.GetByIdForUpdateAsync(org,id,ct);return p is null?Result.Failure<RemediationPlan>(RemediationPlanApplicationErrors.NotFound):Result.Success(p);}protected async Task<Result>Save(Result r,CancellationToken ct){if(r.IsFailure)return r;await uow.CommitAsync(ct);return Result.Success();}}
public sealed class ActivateRemediationPlanCommandHandler(IRemediationPlanRepository p,ICurriculumPedagogyUnitOfWork u,IClock clock):RemediationMutationBase(p,u),ICommandHandler<ActivateRemediationPlanCommand>{public async Task<Result>Handle(ActivateRemediationPlanCommand c,CancellationToken ct){var x=await Load(c.OrganizationId,c.PlanId,ct);return x.IsFailure?Result.Failure(x.Error):await Save(x.Value.Activate(clock.UtcNow),ct);}}
public sealed class CompleteRemediationPlanCommandHandler(IRemediationPlanRepository p,ICurriculumPedagogyUnitOfWork u,IClock clock):RemediationMutationBase(p,u),ICommandHandler<CompleteRemediationPlanCommand>{public async Task<Result>Handle(CompleteRemediationPlanCommand c,CancellationToken ct){var x=await Load(c.OrganizationId,c.PlanId,ct);return x.IsFailure?Result.Failure(x.Error):await Save(x.Value.Complete(clock.UtcNow),ct);}}
public sealed class CancelRemediationPlanCommandHandler(IRemediationPlanRepository p,ICurriculumPedagogyUnitOfWork u,IClock clock):RemediationMutationBase(p,u),ICommandHandler<CancelRemediationPlanCommand>{public async Task<Result>Handle(CancelRemediationPlanCommand c,CancellationToken ct){var x=await Load(c.OrganizationId,c.PlanId,ct);return x.IsFailure?Result.Failure(x.Error):await Save(x.Value.Cancel(c.Reason,clock.UtcNow),ct);}}
